 *  2. `onhost-store.js` → `api/onhost-store.api.js`, `onhost-integrations.js`/`onhost-domains.js` → API-backed variants;
 *  3. `onhost-data.js` → server-generated `/surfaces/onhost-data.js`;
 *  4. injected `window.ONHOST = { apiBase, csrf, user, surface, demo }` + session bridge before `onhost-shell.js`;
 *  5. panel only: `SVC_DATA().services` / `state.servers` read `window.ONHOST_PANEL`, `liveSimulation` defaults to false.
 * Nothing visual is touched: typography, tokens, spacing and components stay as designed.
 */";s:61:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀namespace";s:16:"App\Http\Support";s:56:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀uses";a:2:{s:5:"cache";s:32:"Illuminate\Support\Facades\Cache";s:3:"log";s:30:"Illuminate\Support\Facades\Log";}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀constUses";a:0:{}}s:59:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀abstract";b:0;s:56:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀final";b:1;s:58:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀extends";N;s:61:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀implements";a:0:{}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀usedTraits";a:0:{}s:70:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀traitUseAdaptations";a:0:{}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀statements";a:12:{i:0;O:58:"PHPStan\Dependency\ExportedNode\ExportedClassConstantsNode":5:{s:69:"␀PHPStan\Dependency\ExportedNode\ExportedClassConstantsNode␀constants";a:1:{i:0;O:57:"PHPStan\Dependency\ExportedNode\ExportedClassConstantNode":3:{s:63:"␀PHPStan\Dependency\ExportedNode\ExportedClassConstantNode␀name";s:8:"SURFACES";s:64:"␀PHPStan\Dependency\ExportedNode\ExportedClassConstantNode␀value";s:212:"['public' => 'Onhost.dc.html', 'panel' => 'Onhost-app.dc.html', 'admin' => 'Onhost-admin.dc.html', 'partner' => 'Onhost-partner.dc.html', 'mobile' => 'Onhost-mobil.dc.html', 'widgets' => 'Onhost-widgets.dc.html']";s:69:"␀PHPStan\Dependency\ExportedNode\ExportedClassConstantNode␀attributes";a:0:{}}}s:66:"␀PHPStan\Dependency\ExportedNode\ExportedClassConstantsNode␀public";b:1;s:67:"␀PHPStan\Dependency\ExportedNode\ExportedClassConstantsNode␀private";b:0;s:65:"␀PHPStan\Dependency\ExportedNode\ExportedClassConstantsNode␀final";b:0;s:66:"␀PHPStan\Dependency\ExportedNode\ExportedClassConstantsNode␀phpDoc";N;}i:1;O:50:"PHPStan\Dependency\ExportedNode\ExportedMethodNode":11:{s:56:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀name";s:11:"__