hema";s:33:"Illuminate\Support\Facades\Schema";s:14:"queueheartbeat";s:46:"Onhost\Domain\Provisioning\Jobs\QueueHeartbeat";s:9:"operation";s:43:"Onhost\Domain\Provisioning\Models\Operation";s:11:"domainerror";s:34:"Onhost\Platform\Errors\DomainError";s:13:"settingsstore";s:38:"Onhost\Platform\Settings\SettingsStore";}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀constUses";a:0:{}}}i:4;O:58:"PHPStan\Dependency\ExportedNode\ExportedClassConstantsNode":5:{s:69:"␀PHPStan\Dependency\ExportedNode\ExportedClassConstantsNode␀constants";a:1:{i:0;O:57:"PHPStan\Dependency\ExportedNode\ExportedClassConstantNode":3:{s:63:"␀PHPStan\Dependency\ExportedNode\ExportedClassConstantNode␀name";s:5:"RULES";s:64:"␀PHPStan\Dependency\ExportedNode\ExportedClassConstantNode␀value";s:5398:"[['key' => 'provisioning.tick', 'command' => 'onhost:provisioning:tick', 'name' => 'Provisioning', 'does' => 'spouští splatné operace a oživuje zaseknuté', 'runs' => 'každou minutu', 'switchable' => false], ['key' => 'integrations.health', 'command' => 'onhost:integrations:health', 'name' => 'Zdraví integrací', 'does' => 'ping každé instance panelu, výpadek = interní oznámení; hlídá i frontu úloh', 'runs' => 'každou minutu', 'switchable' => false], ['key' => 'usage.watch', 'command' => 'onhost:services:usage-watch', 'name' => 'Hlídání využití tarifu', 'does' => 'při 85/95 % upozorní; s politikou služby objedná vyšší tarif z kreditu', 'runs' => 'každou hodinu', 'switchable' => true], ['key' => 'renewal.guard', 'command' => 'onhost:billing:renewal-guard', 'name' => 'Ochrana obnov', 'does' => 'týden před obnovou porovná kredit; chybí-li, dobije z uložené karty nebo upozorní', 'runs' => 'denně 07:35', 'switchable' => true], ['key' => 'operations.board', 'command' => 'onhost:provisioning:board', 'name' => 'Automatické odstavení uzlu', 'does' => 'uzel s přechodnými chybami odstaví; po zdravých sondách vrátí', 'runs' => 'každých 5 minut', 'switchable' => true], ['key' => 'nodes.check', 'command' => 'onhost:nodes:check', 'name' => 'Prerekvizity uzlů', 'does' => 'API, verze PHP, cron API, shellová sonda, herní panel; funkce se nabízejí jen kde fungují', 'runs' => 'denně 05:20', 'switchable' => true], ['key' => 'certificates.issue', 'command' => 'onhost:certificates:issue-pending', 'name' => 'Automatické certifikáty', 'does' => 'vystaví certifikát, jakmile DNS domény ukazuje na nás', 'runs' => 'každých 15 minut', 'switchable' => true], ['key' => 'backups.run', 'command' => 'onhost:backups:run', 'name' => 'Zálohy podle plánu', 'does' => 'spouští zálohy podle tarifu a uklízí staré generace', 'runs' => 'každých 15 minut', 'switchable' => true], ['key' => 'digest.weekly', 'command' => 'onhost:digest:weekly', 'name' => 'Týdenní přehled zákazníkům', 'does' => 'obnovy, kredit, zálohy, monitoring; frekvenci určuje zákazník', 'runs' => 'pondělí 07:00', 'switchable' => true], ['key' => 'digest.staff', 'command' => 'onhost:digest:staff-daily', 'name' => 'Denní provozní přehled', 'does' => 'zaseknuté operace, selhání, pohledávky, kapacita', 'runs' => 'denně 07:15', 'switchable' => true], ['key' => 'commerce.prune', 'command' => 'onhost:commerce:prune', 'name' => 'Úklid obchodu', 'does' => 'maže staré nabídky a opuštěné košíky', 'runs' => 'denně 04:20', 'switchable' => true], ['key' => 'order.risk', 'command' => null, 'name' => 'Kontrola objednávek', 'does' => 'skóre rizika při objednávce; nad prahem čeká zaplacená objednávka na rozhodnutí', 'runs' => 'při každé objednávce', 'switchable' => true], ['key' => 'partners.auto_approve', 'command' => null, 'name' => 'Automatické schválení smluvních změn', 'does' => 'zámek sazby do 6 měsíců a výplatní podmínky partnera s čistým rokem schválí bez financí; model a white-label vždy čekají', 'runs' => 'při každé žádosti', 'switchable' => true], ['key' => 'capacity.auto_order', 'command' => 'onhost:provisioning:capacity-forecast', 'name' => 'Automatický nákup uzlů', 'does' => 'schválí a objedná uzel u dodavatele, když fond dochází a instance umí objednávat (jinak jen návrh pro provoz)', 'runs' => 'denně 03:45', 'switchable' => true, 'default_off' => true], ['key' => 'oncall.escalate', 'command' => 'onhost:oncall:escalate', 'name' => 'Eskalace on-call', 'does' => 'alert, který nikdo nepotvrdil do X minut, znovu zavolá pager s vyšší závažností (nejvýš N×)', 'runs' => 'každou minutu', 'switchable' => true], ['key' => 'platform.backup', 'command' => 'onhost:platform:backup', 'name' => 'Záloha platformy', 'does' => 'denně zálohuje databázi control plane a soukromé soubory (doklady, důkazy, exporty) na zálohovací disk a ověřuje obnovitelnost', 'runs' => 'denně 02:15, ověření 03:15', 'switchable' => true], ['key' => 'oncall.remind', 'command' => 'onhost:oncall:remind', 'name' => 'Připomenutí on-call směny', 'does' => 'hodinu před začátkem směny pošle jejímu držiteli upozornění a e-mail', 'runs' => 'každých 5 minut', 'switchable' => true], ['key' => 'game.templates.verify', 'command' => 'onhost:game:templates:verify', 'name' => 'Kontrola herních šablon', 'does' => 'porovná namapované šablony s eggy panelu; chybějící odebere z nabídky a ohlásí provozu, povinné proměnné načte znovu', 'runs' => 'denně 05:10', 'switchable' => true], ['key' => 'files.scan', 'command' => 'onhost:files:scan', 'name' => 'Antivirová kontrola souborů', 'does' => 'znovu prověří soubory, které ClamAV při nahrání nestihl; infikované smaže a nahlásí bezpečnosti', 'runs' => 'každých 10 minut', 'switchable' => false], ['key' => 'files.prune', 'command' => 'onhost:files:prune', 'name' => 'Retence souborů', 'does' => 'maže důkazy z marketplace po retenční lhůtě a exporty dat po expiraci', 'runs' => 'denně 04:25', 'switchable' => true], ['key' => 'game.migration', 'command' => null, 'name' => 'Stěhování herních serverů', 'does' => 'záloha, nový server na jiném uzlu, přenos archivu, přepnutí adresy, úklid — bez zásahu do hry', 'runs' => 'na pokyn obsluhy', 'switchable' => false]]";s:69:"␀PHPStan\Dependency\ExportedNode\ExportedClassConstantNode␀