#cloud-config
# ONhost vendor node bootstrap (audit §5o-7): base packages, the operator's key, then the readiness call-back.
package_update: true
packages: [curl, ca-certificates, python3, sudo]
ssh_authorized_keys:
  - "{ssh_key}"
runcmd:
  - [sh, -c, "hostnamectl set-hostname $(hostname) || true"]
  - [sh, -c, "curl -fsS -X POST '{callback}' -H 'Content-Type: application/json' -d \"{\\\"token\\\":\\\"{token}\\\",\\\"hostname\\\":\\\"$(hostname)\\\",\\\"ip\\\":\\\"$(hostname -I | awk '{print $1}')\\\",\\\"os\\\":\\\"$(. /etc/os-release; echo $PRETTY_NAME)\\\",\\\"cpu_cores\\\":$(nproc),\\\"ram_mb\\\":$(free -m | awk '/Mem:/{print $2}'),\\\"disk_gb\\\":$(df -BG --output=size / | tail -1 | tr -dc 0-9)}\" || true"]
YAML";s:69:"␀PHPStan\Dependency\ExportedNode\ExportedClassConstantNode␀attributes";a:0:{}}}s:66:"␀PHPStan\Dependency\ExportedNode\ExportedClassConstantsNode␀public";b:1;s:67:"␀PHPStan\Dependency\ExportedNode\ExportedClassConstantsNode␀private";b:0;s:65:"␀PHPStan\Dependency\ExportedNode\ExportedClassConstantsNode␀final";b:0;s:66:"␀PHPStan\Dependency\ExportedNode\ExportedClassConstantsNode␀phpDoc";N;}}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀attributes";a:0:{}}}}9955
