a:1:{s:53:"../../../providers/Subreg/SubregRegistrarProvider.php";a:1:{i:0;O:49:"PHPStan\Dependency\ExportedNode\ExportedClassNode":10:{s:55:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀name";s:47:"Onhost\Providers\Subreg\SubregRegistrarProvider";s:57:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀phpDoc";O:50:"PHPStan\Dependency\ExportedNode\ExportedPhpDocNode":4:{s:64:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀phpDocString";s:531:"/**
 * Subreg.CZ registrar (https://subreg.cz/manual/). Only the domain registration /
 * editing / management functions are used — never the hosting families. Every
 * mutation is a Subreg *order* (`Make_Order`) that completes asynchronously; the
 * order id travels in the AsyncHandle and `awaitStatus` resolves it through
 * `Info_Order` + `Info_Domain`, so a timeout is never resolved by resending (S34).
 * Wholesale prices come from `Prices` (per TLD) and feed the cheapest-registrar
 * selection (`RegistrarSelector`).
 */";s:61:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀namespace";s:23:"Onhost\Providers\Subreg";s:56:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀uses";a:12:{s:15:"cacherepository";s:37:"Illuminate\Contracts\Cache\Repository";s:16:"providerinstance";s:50:"Onhost\Domain\Provisioning\Models\ProviderInstance";s:17:"providererrorcode";s:40:"Onhost\Platform\Errors\ProviderErrorCode";s:17:"providerexception";s:40:"Onhost\Platform\Errors\ProviderException";s:18:"providerhttpclient";s:47:"Onhost\Platform\ProviderHttp\ProviderHttpClient";s:11:"asynchandle";s:38:"Onhost\Providers\Contracts\AsyncHandle";s:11:"asyncstatus";s:38:"Onhost\Providers\Contracts\AsyncStatus";s:14:"providerhealth";s:41:"Onhost\Providers\Contracts\ProviderHealth";s:14:"providerresult";s:41:"Onhost\Providers\Contracts\ProviderResult";s:24:"registrarpricingprovider";s:51:"Onhost\Providers\Contracts\RegistrarPricingProvider";s:17:"registrarprovider";s:44:"Onhost\Providers\Contracts\RegistrarProvider";s:11:"resourceref";s:38:"Onhost\Providers\Contracts\ResourceRef";}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀constUses";a:0:{}}s:59:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀abstract";b:0;s:56:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀final";b:1;s:58:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀extends";N;s:61:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀implements";a:2:{i:0;s:51:"Onhost\Providers\Contracts\RegistrarPricingProvider";i:1;s:44:"Onhost\Providers\Contracts\RegistrarProvider";}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀usedTraits";a:0:{}s:70:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀traitUseAdaptations";a:0:{}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀statements";a:31:{i:0;O:50:"PHPStan\Dependency\ExportedNode\ExportedMethodNode":11:{s:56:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀name";s:11:"__construct";s:58:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀phpDoc";N;s:57:"␀PHPStan